<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title><?= html_escape($store['display_name']) ?> — Rembang UMKM</title><link rel="icon" href="<?= base_url('assets/favicon.ico?v=1') ?>"><link rel="stylesheet" href="<?= base_url('assets/tabler.min.css') ?>"><link rel="stylesheet" href="<?= base_url('assets/leaflet/leaflet.css') ?>"><link rel="stylesheet" href="<?= base_url('assets/marketplace.css?v=5') ?>"><link rel="stylesheet" href="<?= base_url('assets/market-nearby.css?v=3') ?>"></head><body class="shop-body"><?php $this->load->view('market/_header'); ?><main class="shop-main container-xl"><nav class="shop-breadcrumb"><a href="<?= site_url('jelajah') ?>">Beranda</a><span>›</span><a href="<?= site_url('daftar-toko') ?>">Toko</a><span>›</span><strong><?= html_escape($store['display_name']) ?></strong></nav><div class="shop-category-grid shop-category-shortcuts"><a class="shop-category-item" href="<?= site_url('daftar-toko') ?>"><span class="shop-category-art all" aria-hidden="true"><svg viewBox="0 0 96 96"><circle cx="29" cy="29" r="11"/><circle cx="67" cy="29" r="11"/><circle cx="29" cy="67" r="11"/><circle cx="67" cy="67" r="11"/></svg></span><span>Semua toko</span></a><?php $this->load->view('market/_nearby_action',array('nearby'=>NULL,'target'=>site_url('daftar-toko'))); ?></div><section class="shop-store-profile"><div class="shop-store-profile-icon"><img src="<?= category_art_url($categories ? $categories[0]['slug'] : 'ritel') ?>" alt=""></div><div><span class="shop-eyebrow">TOKO LOKAL REMBANG</span><h1><?= html_escape($store['display_name']) ?></h1><p><?= html_escape($store['description'] ?: 'Pilihan produk lokal dari Rembang.') ?></p><div class="shop-store-meta"><span>⌖ <?= html_escape($store['district_name'] ?: 'Rembang') ?></span><span>◈ <?= count($products) ?> produk</span></div><div class="shop-store-tags"><?php foreach ($categories as $category): ?><span><?= html_escape($category['name']) ?></span><?php endforeach; ?></div></div><form class="shop-store-chat" method="post" action="<?= site_url('kontak/toko') ?>"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><input type="hidden" name="store_slug" value="<?= html_escape($store['slug']) ?>"><button type="submit">Tanya Penjual <span aria-hidden="true">↗</span></button></form></section><section class="shop-products-section"><div class="shop-section-head"><div><span class="shop-eyebrow">DARI TOKO INI</span><h2>Semua produk</h2></div><span class="shop-result-count"><?= count($products) ?> produk</span></div><?php if (!$products): ?><div class="shop-empty"><strong>Produk belum tersedia</strong></div><?php else: ?><div class="shop-product-grid"><?php foreach ($products as $product): ?><article class="shop-product-card"><a class="shop-product-link" href="<?= site_url('produk/'.$product['id']) ?>"><div class="shop-product-image <?= $product['cover_path'] ? 'has-photo' : '' ?>"><img src="<?= ($product['cover_path'] ? base_url('assets/products/'.rawurlencode($product['cover_path'])) : category_art_url($product['category_slug'] ?: 'kuliner')) ?>" alt="" loading="lazy"></div><div class="shop-product-info"><h3><?= html_escape($product['name']) ?></h3><strong><?= $product['price_min'] !== NULL ? 'Rp'.number_format((float)$product['price_min'],0,',','.') : 'Tanya harga' ?></strong><small><?= html_escape($store['display_name']) ?></small></div></a><?php if ((int)$product['variant_count']>0): ?><a class="shop-quick-add shop-choose-variant" href="<?= site_url('produk/'.$product['id']) ?>" aria-label="Pilih variasi <?= html_escape($product['name']) ?>">Pilih</a><?php else: ?><form method="post" action="<?= site_url('keranjang/tambah') ?>" class="shop-quick-add"><input type="hidden" name="<?= $this->security->get_csrf_token_name() ?>" value="<?= $this->security->get_csrf_hash() ?>"><input type="hidden" name="product_id" value="<?= (int)$product['id'] ?>"><input type="hidden" name="quantity" value="1"><button type="submit" aria-label="Tambah <?= html_escape($product['name']) ?> ke keranjang">+</button></form><?php endif; ?></article><?php endforeach; ?></div><?php endif; ?></section><?php $this->load->view('market/_store_hours',array('hours'=>$hours)); ?><section class="shop-store-location"><div class="shop-section-head"><div><span class="shop-eyebrow">AREA TOKO</span><h2>Lokasi di peta</h2></div><a href="<?= site_url('peta').'?district='.(int)$store['district_id'] ?>">Buka peta →</a></div><?php if ($store['map_latitude'] !== NULL && $store['map_longitude'] !== NULL): ?><div id="shop-store-map" aria-label="Peta lokasi toko"></div><p><?= $store['exact_location'] ? 'Lokasi toko yang disetujui untuk ditampilkan.' : 'Penanda menunjukkan area Kecamatan '.html_escape($store['district_name']).', bukan alamat persis toko.' ?></p><?php else: ?><p>Lokasi toko belum tersedia di peta.</p><?php endif; ?></section></main><?php $active_tab='stores';$this->load->view('market/_bottom_nav', array('active_tab' => $active_tab, 'cart_count' => $cart_count)); ?><?php if ($store['map_latitude'] !== NULL && $store['map_longitude'] !== NULL): ?><script src="<?= base_url('assets/leaflet/leaflet.js') ?>"></script><script>(function(){const lat=<?= json_encode((float)$store['map_latitude']) ?>,lng=<?= json_encode((float)$store['map_longitude']) ?>,exact=<?= $store['exact_location'] ? 'true' : 'false' ?>;const map=L.map('shop-store-map',{scrollWheelZoom:false}).setView([lat,lng],exact?15:12);L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);L.circleMarker([lat,lng],{radius:exact?10:14,color:'#fff',weight:3,fillColor:exact?'#ed8237':'#2673c7',fillOpacity:.95}).addTo(map);})();</script><?php endif; ?></body></html>
